package toolschema

func sendMessageFields() []Field {
	shutdown := Schema{Kind: "object", Native: true, UnknownKeys: "strip", Fields: []Field{{"type", Schema{Kind: "literal", Native: true, Literal: quote("shutdown_request")}}, {"reason", Schema{Kind: "string", Optional: true}}}}
	response := Schema{Kind: "object", Native: true, UnknownKeys: "strip", Fields: []Field{{"type", Schema{Kind: "literal", Native: true, Literal: quote("shutdown_response")}}, {"request_id", Schema{Kind: "string"}}, {"approve", Schema{Kind: "boolean", Semantic: true}}, {"reason", Schema{Kind: "string", Optional: true}}}}
	plan := Schema{Kind: "object", Native: true, UnknownKeys: "strip", Fields: []Field{{"type", Schema{Kind: "literal", Native: true, Literal: quote("plan_approval_response")}}, {"request_id", Schema{Kind: "string"}}, {"approve", Schema{Kind: "boolean", Semantic: true}}, {"feedback", Schema{Kind: "string", Optional: true}}}}
	structured := Schema{Kind: "union", Native: true, Discriminator: "type", Members: []Schema{shutdown, response, plan}}
	return []Field{{"to", textSchema("Recipient: teammate name, or \"*\" for broadcast to all teammates", false)}, {"summary", textSchema("A 5-10 word summary shown as a preview in the UI (required when message is a string)", true)}, {"message", Schema{Kind: "union", Native: true, Members: []Schema{textSchema("Plain text message content", false), structured}}}}
}

const sendMessagePrompt = "# SendMessage\n\nSend a message to another agent.\n\n```json\n{\"to\": \"researcher\", \"summary\": \"assign task 1\", \"message\": \"start on task #1\"}\n```\n\n| `to` | |\n|---|---|\n| `\"researcher\"` | Teammate by name |\n| `\"*\"` | Broadcast to all teammates — expensive (linear in team size), use only when everyone genuinely needs it |\n\nYour plain text output is NOT visible to other agents — to communicate, you MUST call this tool. Messages from teammates are delivered automatically; you don't check an inbox. Refer to teammates by name, never by UUID. When relaying, don't quote the original — it's already rendered to the user.\n\n## Protocol responses (legacy)\n\nIf you receive a JSON message with `type: \"shutdown_request\"` or `type: \"plan_approval_request\"`, respond with the matching `_response` type — echo the `request_id`, set `approve` true/false:\n\n```json\n{\"to\": \"team-lead\", \"message\": {\"type\": \"shutdown_response\", \"request_id\": \"...\", \"approve\": true}}\n{\"to\": \"researcher\", \"message\": {\"type\": \"plan_approval_response\", \"request_id\": \"...\", \"approve\": false, \"feedback\": \"add error handling\"}}\n```\n\nApproving shutdown terminates your process. Rejecting plan sends the teammate back to revise. Don't originate `shutdown_request` unless asked. Don't send structured JSON status messages — use TaskUpdate."
